-- --- line breaks at the danda, for mantras still stored as one run ------------
update public.pooja_steps set
  mantra_sanskrit = replace(replace(mantra_sanskrit, '। ', '।' || chr(10)), '॥ ', '॥' || chr(10)),
  mantra_tamil = replace(replace(mantra_tamil, '। ', '।' || chr(10)), '॥ ', '॥' || chr(10)),
  mantra_translit = replace(replace(mantra_translit, '। ', '।' || chr(10)), '॥ ', '॥' || chr(10)),
  updated_at = now()
where step_title_en in ('Achamanam', 'Anga Vandanam', 'Manjal Pillaiyar Pooja')
  and mantra_sanskrit is not null
  and mantra_sanskrit not like '%' || chr(10) || '%';

-- --- assert -------------------------------------------------------------------
do $$
declare n int;
begin
  -- Nothing anywhere may still be an unreviewed draft.
  select count(*) into n from public.pooja_steps
   where source_ref is null or source_ref like '%pending vaidika review%';
  if n > 0 then raise exception '% steps are still unsourced drafts', n; end if;
  -- Both sankalpams keep the slot, in all three scripts.
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Sankalpam'
     and mantra_sanskrit like '%[DYNAMIC_PANCHANGAM_DATA]%'
     and mantra_tamil like '%[DYNAMIC_PANCHANGAM_DATA]%'
     and mantra_translit like '%[DYNAMIC_PANCHANGAM_DATA]%';
  if n <> 2 then raise exception 'expected 2 sankalpams with the slot intact, found %', n; end if;
  -- No ellipsis, no back-reference, no hardcoded lunar month.
  select count(*) into n from public.pooja_steps
   where step_title_en = 'Sankalpam'
     and (position('...' in mantra_sanskrit) > 0
          or mantra_sanskrit like '%पूर्वोक्त%' or mantra_sanskrit like '%भाद्रपद%');
  if n > 0 then raise exception '% sankalpams still carry a removed phrase', n; end if;
  -- Every mantra that is meant to read as verses is on more than one line.
  select count(*) into n from public.pooja_steps
   where step_title_en in ('Achamanam', 'Anga Vandanam', 'Manjal Pillaiyar Pooja')
     and mantra_sanskrit not like '%' || chr(10) || '%';
  if n > 0 then raise exception '% formatted steps are still a single line', n; end if;
  -- A line break must not have been inserted into the middle of a word.
  select count(*) into n from public.pooja_steps
   where mantra_sanskrit like '%' || chr(10) || ' %' or mantra_sanskrit like '% ' || chr(10) || '%';
  if n > 0 then raise exception '% mantras have a space beside a line break', n; end if;
end $$;

commit;

